INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 1, 5, 'go',
  'Peak Wayanad window. 12-28C across the 700-2100m range. Edakkal Caves, Chembra Peak, Banasura Sagar, WLS at full tempo.',
  'January is when Wayanad runs at its post-monsoon peak. Edakkal Caves (₹100, 9am-5pm closed Mon, 700-step climb) at full hours. Chembra Peak (2050m, online booking ₹750, advance 2-3 days) — heart-shaped lake midway. Wayanad WLS jeep safari (Forest Dept, ₹400, 7-9am + 3-4pm batches).',
  NULL,
  'Wayanad in January is the version every Western Ghats traveller wants to see. The district straddles 700-2100m altitude across coffee, cardamom and pepper agriculture, with the Wayanad Wildlife Sanctuary forming the Kerala wing of the Nilgiri Biosphere Reserve. Daytime 22-28C at lower elevations (Sulthan Bathery, Kalpetta), 12-18C at the 2000m belt (Chembra Peak base, Banasura Sagar Dam), nights 12-16C. Edakkal Caves — the 8000-year-old petroglyphs on Ambukutty Mala, 2-tier cave, climb of 700 steps to the entrance — runs ₹100 entry, 9am-5pm, closed Monday, advance booking via the Kerala Tourism portal recommended for weekend visits. Chembra Peak (2050m) — the heart-shaped lake midway through the 7km trek — operates from the Meppadi-side Forest Department gate, online booking ₹750 per group, advance 2-3 days. Banasura Sagar Dam (largest earth dam in India, 685m length, 38.5m height) at full visitor hours 9am-6pm with KTDC speedboat operations ₹50/person. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) jeep safari ₹400/person via the Forest Department, 7-9am and 3-4pm batches, advance booking 1-2 days at muthanga.kerala.gov.in. Tigers, wild elephants, gaur, Malabar Giant Squirrel, 200+ bird species. Stays cluster at Kalpetta, Vythiri, Sulthan Bathery: homestays ₹1,500-3,500, mid-bracket resorts (Vythiri Resort, Banasura Hill, Wayanad Wild) ₹6-12k, luxury bracket (Wayanad Silver Woods, Stone Castle) ₹14-25k.'
)
ON CONFLICT (destination_id, month) DO UPDATE SET
  score = EXCLUDED.score, verdict = EXCLUDED.verdict, note = EXCLUDED.note,
  why_go = EXCLUDED.why_go, why_not = EXCLUDED.why_not, prose_lead = EXCLUDED.prose_lead;

INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 2, 5, 'go',
  'Driest month. 14-30C. Edakkal, Chembra, Banasura, WLS at full tempo. Coffee flowering visible.',
  'February is the cleanest weather month at Wayanad — rainfall under 25mm, trails firm, coffee flowering visible at higher-elevation estates (Robusta variety). Hotel rates 25 percent below January peak. Strong window for first-time district visitors.',
  NULL,
  'Wayanad in February is the technical sweet spot. Rainfall averages 20-25mm, daytime 19-30C across the elevation range (cooler at the 2000m belt), nights 14-18C. Edakkal Caves (8000-year-old petroglyphs on Ambukutty Mala, 2-tier cave, 700-step climb, ₹100 entry, 9am-5pm closed Mon) at full operational tempo. Chembra Peak (2050m) — the famous heart-shaped lake midway, 7km moderate trek — operates from the Meppadi Forest Department gate, online booking ₹750 per group, advance 2-3 days. Banasura Sagar Dam (largest earth dam in India, 685m length) at full visitor hours 9am-6pm, KTDC speedboat operations ₹50/person. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) Forest Department jeep safari ₹400/person, 7-9am and 3-4pm batches, online booking at muthanga.kerala.gov.in 1-2 days ahead. Tigers (Wayanad-Bandipur-Mudumalai-Nagarhole tiger landscape — one of India''s densest), wild elephants, gaur, Malabar Giant Squirrel at year-best concentration. Coffee flowering visible at higher-elevation estates around Meppadi and Sultan Bathery — Robusta variety hits the 3-4 week pre-monsoon flowering window. Hotel rates drop 25 percent versus January: homestays at ₹1,200-3,000, mid-bracket resorts at ₹5,000-10,000, luxury at ₹12-22k. The 6-hour drive from Kozhikode airport (Calicut, 100km via Tamarassery Ghat with 9 hairpins) at year-clearest visibility.'
)
