INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 3, 4, 'go',
  'Last cool month. 16-32C. Coffee flowering peaks. Wildlife waterhole concentration begins.',
  'March extends February''s pattern. Coffee flowering hits visible peak at established estates. Wildlife concentration at remaining waterholes begins building — WLS jeep safari sighting odds climb. Hotel rates 30 percent below January.',
  NULL,
  'Wayanad in March is the soft-landing month with the bonus of coffee flowering. Daytime 21-32C at lower elevations (Kalpetta, Sulthan Bathery), 16-22C at the 2000m belt, humidity climbing toward 70 percent in the last fortnight, rainfall under 40mm. Coffee flowering peaks at established estates around Meppadi, Mananthavady and Sulthan Bathery — Robusta variety hits its visible flush, 3-4 week pre-monsoon window unique to March, plantation walks at ₹500-800. Edakkal Caves (8000-year-old petroglyphs, 700-step climb to the 2-tier cave, ₹100, 9am-5pm closed Mon) at year-clearest visibility. Chembra Peak (2050m) — heart-shaped lake midway, 7km trek — at peak photographic interest with coffee-flush backdrop, online booking ₹750 per group at the Meppadi Forest Department gate, advance 2-3 days. Banasura Sagar Dam (685m length, India''s largest earth dam) full hours 9am-6pm. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga, Forest Department jeep safari ₹400, 7-9am and 3-4pm batches at muthanga.kerala.gov.in) at year-best wildlife concentration as waterholes shrink — tiger sighting odds climb, elephant in 4-6 sightings per safari, Malabar Giant Squirrel at every fig tree. Holi long weekend brings a 3-day domestic bump. Hotel rates drop 30 percent versus January: homestays at ₹1,000-2,500, mid-bracket resorts at ₹4,500-9,000, luxury at ₹10-19k.'
)
