INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 4, 4, 'go',
  'Wildlife concentration peaks. 18-34C. WLS sightings at year-best. Trails dawn-dusk only.',
  'April is when Wayanad WLS wildlife sighting odds peak — water sources at year-low, animals concentrate visibly. Tiger, elephant, gaur sightings climb. Trails compress to dawn-dusk windows. Hotel rates 35 percent below January.',
  NULL,
  'Wayanad in April is the peak wildlife-concentration window with the heat-compromise. Daytime 23-34C at lower elevations, 18-26C at the 2000m belt, humidity past 75 percent in the last fortnight. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) jeep safari sighting odds peak — the sanctuary is part of the Wayanad-Bandipur-Mudumalai-Nagarhole landscape, one of India''s densest tiger habitats; tiger sightings climb to 1-in-12 safaris (versus 1-in-25 January), elephant in 5-7 herd sightings, gaur in 8-12 individuals, Malabar Giant Squirrel at concentration peak. Forest Department jeep safari ₹400/person, 7-9am and 3-4pm batches, online booking at muthanga.kerala.gov.in 2-3 days ahead. Edakkal Caves (8000-year-old petroglyphs, 700-step climb, ₹100, 9am-5pm closed Mon) workable only 7-10am before mid-day heat. Chembra Peak (2050m, 7km trek, ₹750 group, online via Meppadi Forest Department) — start by 6am to descend before mid-day heat. Banasura Sagar Dam (685m length) full hours but speedboat operations slow on hot afternoons. Vishu (April 14, Malayalam new year) brings a 3-day domestic bump. Pre-monsoon thunderstorms from April 22-28 bring 50-80mm overnight rains. Hotel rates 35 percent below January: homestays at ₹900-2,200, mid-bracket resorts at ₹4,000-8,000, luxury at ₹9-16k.'
)
