INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 5, 3, 'wait',
  'Pre-monsoon. 20-34C. First fortnight workable, last 10 days bring SW-monsoon advance squalls.',
  'Early May extends April — wildlife concentration at peak, jeep safari at year-best. Last 10 days bring SW-monsoon advance squalls; Chembra trek and Edakkal climb compress on rainy afternoons. Hotel rates at year-low. Push to October if landslide-risk awareness matters.',
  'May splits cleanly in two — first fortnight workable (WLS jeep safari at peak sighting odds, Edakkal Caves and Chembra trek workable dawn windows), last 10 days bring SW-monsoon advance squalls. Wayanad receives heavy monsoon rainfall (4,000-6,000mm annual); the last fortnight gets the first taste.',
  'Wayanad in May splits cleanly in two. The first fortnight extends April: daytime 23-34C at lower elevations, 20-28C at the 2000m belt, humidity 75-80 percent. Wayanad Wildlife Sanctuary jeep safari (Tholpetty + Muthanga, ₹400/person, 7-9am and 3-4pm batches at muthanga.kerala.gov.in) at peak wildlife-concentration sighting odds. Edakkal Caves (8000-year-old petroglyphs, 700-step climb) and Chembra Peak (2050m, 7km trek, ₹750 group at Meppadi) workable only 7-10am. By the third week, southwest monsoon advance squalls hit Kerala — Wayanad receives the first of the season''s 4,000-6,000mm annual rainfall, typically as 1-2 hour afternoon downpours. Chembra trek closes on rainy afternoons (Forest Department safety rule); Edakkal 700-step climb gets slick and slippery. Banasura Sagar Dam (685m length) speedboat operations suspend on rough-water days. Pre-monsoon thunderstorms knock electric supply 2-4 hours daily. Hotel rates at year-low: homestays at ₹800-2,000, mid-bracket resorts at ₹3,500-7,000, luxury at ₹8-14k. Lock the first 10 days; gamble or skip the last fortnight. The 6-hour Kozhikode-Wayanad drive (100km via Tamarassery Ghat 9 hairpins) gets first landslide-watch from May 22.'
)
ON CONFLICT (destination_id, month) DO UPDATE SET
  score = EXCLUDED.score, verdict = EXCLUDED.verdict, note = EXCLUDED.note,
  why_go = EXCLUDED.why_go, why_not = EXCLUDED.why_not, prose_lead = EXCLUDED.prose_lead;

INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 6, 1, 'skip',
  'SW monsoon onset. 18-26C, 800-1000mm rainfall. LANDSLIDE RISK serious — 2024 Mundakkai disaster context. Skip.',
  NULL,
  'June is when the southwest monsoon hits Wayanad with full force — 800-1000mm rainfall, serious landslide risk (Wayanad has been hit by multiple landslides in recent monsoons including the catastrophic 2024 Mundakkai event). Tamarassery Ghat road closures frequent. Skip.',
  'Wayanad in June is when the southwest monsoon hits with full Western Ghats force — and the district carries serious landslide risk that travellers must understand. Rainfall hits 800-1000mm across 22-25 wet days, part of the district''s 4,000-6,000mm annual total. Wayanad has been struck by multiple devastating landslides in recent monsoon seasons, including the catastrophic July 2024 Mundakkai disaster (300+ casualties at Mundakkai-Chooralmala in Meppadi panchayat); Geological Survey of India and Kerala Disaster Management classify large parts of the district as landslide-vulnerable in heavy-rain events. Tamarassery Ghat (the 9-hairpin Kozhikode-Wayanad road, 100km approach) faces 2-3 closure events per week through Kerala PWD clearance. Chembra Peak trek (2050m, online booking ₹750 at Meppadi Forest Department) suspends for the season under Forest Department safety rules. Wayanad WLS jeep safari (Tholpetty + Muthanga) suspends frequently on rough-trail days. Edakkal Caves stays open but the 700-step approach turns slick. Banasura Sagar Dam (685m length) speedboat operations suspend. Coffee plantations at peak monsoon green but plantation walks suspend. Hotel rates at year-low: homestays at ₹700-1,800, mid-bracket resorts at ₹3,000-6,000. The trip you came for cannot happen safely until October.'
)
ON CONFLICT (destination_id, month) DO UPDATE SET
  score = EXCLUDED.score, verdict = EXCLUDED.verdict, note = EXCLUDED.note,
  why_go = EXCLUDED.why_go, why_not = EXCLUDED.why_not, prose_lead = EXCLUDED.prose_lead;

INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 7, 1, 'skip',
  'Peak monsoon. 18-25C, 1200-1500mm rainfall. LANDSLIDE RISK serious. Tamarassery Ghat shut frequently. Skip.',
  NULL,
  'July is the wettest month at Wayanad — 1200-1500mm rainfall, serious landslide risk (2024 Mundakkai disaster occurred end-July), Tamarassery Ghat closures 2-3 days/week. Karkidakam Ayurveda residencies the only valid trip-shape. Skip.',
  'Wayanad in July is the year''s wettest stretch and carries the highest landslide risk of any month. Rainfall hits 1200-1500mm at the 700-2100m elevation range across 25-27 wet days — Wayanad receives some of the heaviest July rainfall in South India alongside Munnar. Daytime 20-25C with 95 percent humidity and constant downpour. The catastrophic Mundakkai-Chooralmala landslide of July 30, 2024 — 300+ casualties in Meppadi panchayat — occurred at the end of this month; Kerala Disaster Management and Geological Survey of India have flagged July as the highest-risk window in the district. Tamarassery Ghat (9-hairpin Kozhikode-Wayanad approach, 100km) faces 2-3 closures per week. Chembra Peak trek (2050m, online booking ₹750 at Meppadi Forest Department) closed for the season under Forest Department safety rules. Wayanad WLS jeep safari (Tholpetty + Muthanga, ₹400/person at muthanga.kerala.gov.in) suspends on most days. Edakkal Caves (8000-year-old petroglyphs, ₹100, 9am-5pm closed Mon) stays open but the 700-step climb is dangerous in rain. Banasura Sagar Dam speedboat operations suspend. Karkidakam — the Malayalam calendar''s monsoon-Ayurveda month (mid-July to mid-August) — is the single legitimate reason to be in the district; Karkidaka Chikitsa packages (14-21 days) at established Ayurveda residencies in the Vythiri-Kalpetta belt discount 30-40 percent. For the standard trip, wait for October.'
)
