INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 8, 1, 'skip',
  'Monsoon continues. 18-25C, 1000-1200mm rainfall. Landslide risk continues. Onam closes town. Skip.',
  NULL,
  'August holds the July pattern — 1000-1200mm rainfall, landslide risk continues. Onam (variable Aug-Sep) shuts most district operations 3-4 days. Karkidakam Ayurveda continues mid-Aug. Wait for October.',
  'Wayanad in August holds the July monsoon pattern with marginally fewer extreme-rain days. Rainfall 1000-1200mm at the 700-2100m elevation range across 22-25 wet days. Daytime 20-25C, 90 percent humidity. Landslide risk continues — Geological Survey of India and Kerala Disaster Management flag the entire June-August window as high-risk in the district given the area''s geology and recent disaster history (2024 Mundakkai). Tamarassery Ghat (9-hairpin Kozhikode-Wayanad approach, 100km) faces 1-2 closures per week. Chembra Peak trek (2050m, ₹750 group at Meppadi Forest Department) remains closed for the season. Wayanad WLS jeep safari (Tholpetty + Muthanga, ₹400/person at muthanga.kerala.gov.in) suspends on most days. Edakkal Caves (₹100, 9am-5pm closed Mon) stays open but the 700-step climb dangerous in rain. Banasura Sagar Dam (685m length, India''s largest earth dam) speedboat operations suspend. Onam — Kerala''s 10-day cultural festival running Atham to Thiruvonam (variable late August into September) — closes most district town shops, restaurants, and resort activities for 3-4 days around Thiruvonam. Karkidakam Ayurveda residencies continue through mid-August. Hotel rates at year-low outside the Onam bump: homestays at ₹700-1,800, mid-bracket at ₹3,000-6,000. Wait for October.'
)
