INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 9, 2, 'wait',
  'Monsoon withdrawing. 18-26C, 500-700mm rainfall easing. Trails reopen progressively. Landslide-watch tail.',
  'September is the recovery month. SW monsoon retreats from the Western Ghats by week three, Forest Department reopens trails progressively, Tamarassery Ghat stabilises. Landslide-watch continues in week one. October is dramatically cleaner.',
  'September is on the way back but Forest Department trail reopenings are progressive — Chembra Peak trek and full WLS safari operations only resume by month-end. Tamarassery Ghat stabilises by mid-month but landslide-watch continues in week one. October is dramatically cleaner.',
  'Wayanad in September is the soft re-opening with progressive trail-by-trail return. Rainfall drops to 500-700mm across 16-18 wet days, mostly the first fortnight. Daytime 20-26C across the elevation range, nights 18-20C, humidity easing toward 80 percent. The southwest monsoon retreats from the Western Ghats by September 20-25; Tamarassery Ghat (9-hairpin Kozhikode-Wayanad approach, 100km) stabilises with closure events dropping to under 1 per week from mid-month. Forest Department reopens Wayanad Wildlife Sanctuary jeep safari progressively from September 20-25 (Tholpetty + Muthanga, ₹400/person at muthanga.kerala.gov.in, 7-9am and 3-4pm batches). Chembra Peak trek (2050m, ₹750 group at Meppadi Forest Department) reopens late month after trail safety certification. Edakkal Caves (8000-year-old petroglyphs, 700-step climb, ₹100, 9am-5pm closed Mon) at full hours. Banasura Sagar Dam (685m length) speedboat operations resume mid-month. Coffee plantations at peak monsoon green flush. Onam tail keeps shops at light hours through the first week. Hotel rates at year-low: homestays at ₹800-1,800, mid-bracket resorts at ₹3,000-6,500. October is the cleaner call.'
)
