INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 10, 4, 'go',
  'Season opens fully. 18-28C, 200-300mm rainfall. WLS, Chembra, Edakkal, Banasura at full tempo. Coffee at year-greenest.',
  'October is the proper season opener. WLS jeep safari + Chembra trek + Edakkal climb all reopen fully, Tamarassery Ghat stable, coffee estates at year-greenest. NE monsoon overspill 200-300mm rain mostly evenings. Hotel rates 30 percent below December.',
  NULL,
  'Wayanad in October is when the district returns to full operations. Daytime 21-28C across the elevation range, nights 18-20C, rainfall 200-300mm — most in the first 10 days, easing through the month — humidity dropping toward 75 percent. Tamarassery Ghat (9-hairpin Kozhikode-Wayanad approach, 100km) stabilises fully by October 15; landslide closures drop to rare events. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) Forest Department jeep safari at full schedule (₹400/person, 7-9am and 3-4pm batches at muthanga.kerala.gov.in, advance booking 1-2 days). Chembra Peak trek (2050m, heart-shaped lake midway, 7km moderate, online booking ₹750 group at Meppadi Forest Department, advance 2-3 days) reopens fully. Edakkal Caves (8000-year-old petroglyphs on Ambukutty Mala, 2-tier cave, 700-step climb, ₹100 entry, 9am-5pm closed Mon) at full hours. Banasura Sagar Dam (685m length, India''s largest earth dam) at full visitor hours 9am-6pm with KTDC speedboat operations ₹50/person. Coffee plantations at year-greenest after the southwest monsoon flush. Wildlife dispersed across abundant water sources but the Western Ghats forest aesthetic at year-best. Hotel rates 30 percent below December peak: homestays at ₹1,000-2,500, mid-bracket resorts at ₹4,000-8,500, luxury at ₹10-18k. Pack a poncho, fleece for hill evenings.'
)
