INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 11, 5, 'go',
  'High season builds. 16-26C, dry. WLS, Chembra, Edakkal, Banasura at peak. Hotel rates climb 25 percent.',
  'November is when Wayanad turns the corner. Northeast monsoon residual eases to under 80mm, district at full operational tempo, WLS sighting odds climb as waterholes shrink. Hotel rates climb 20-25 percent across the month.',
  NULL,
  'Wayanad in November is when the Western Ghats district turns the corner. Northeast monsoon residual eases to under 80mm across 5-7 wet days, almost all in the first ten days. Daytime 19-26C across the elevation range, nights drop to 16-18C in the 2000m belt, humidity dropping under 70 percent in the back half. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) Forest Department jeep safari at full schedule (₹400/person, 7-9am and 3-4pm batches at muthanga.kerala.gov.in) — wildlife sighting odds climb as waterholes shrink, tiger and elephant odds doubled versus October. Chembra Peak trek (2050m, heart-shaped lake midway, 7km moderate, online booking ₹750 group at Meppadi Forest Department) at full schedule, advance 2-3 days. Edakkal Caves (8000-year-old petroglyphs, 700-step climb, ₹100, 9am-5pm closed Mon) at year-clearest visibility. Banasura Sagar Dam (685m length, India''s largest earth dam) at full visitor hours, KTDC speedboat ₹50/person. Coffee plantations at year-clearest visibility. Hotel rates climb 20-25 percent across the month: homestays at ₹1,300-3,000, mid-bracket resorts at ₹5,000-10,000, luxury at ₹12-22k. Concentration of weekend domestic traffic from November 15 onward as Christmas-week families begin booking. Strong call for first-time district visitors.'
)
ON CONFLICT (destination_id, month) DO UPDATE SET
  score = EXCLUDED.score, verdict = EXCLUDED.verdict, note = EXCLUDED.note,
  why_go = EXCLUDED.why_go, why_not = EXCLUDED.why_not, prose_lead = EXCLUDED.prose_lead;

INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('wayanad', 12, 5, 'go',
  'Peak season. 12-26C. Christmas-NY rates 2-2.5x. Chembra slots tight, WLS bookings at 5-7 day lead.',
  'December is the year''s most reliable Wayanad window. Christmas-NY week (Dec 22-Jan 5) drives 2-2.5x rates, Chembra Peak slots tighten to 5-7 day lead, WLS jeep safari bookings at 3-5 days. Tamarassery Ghat at year-busiest.',
  NULL,
  'Wayanad in December is operational peak. Daytime 18-26C across the elevation range, nights drop to 12-16C in the 2000m belt, rainfall under 30mm. Christmas-NY week (December 22 to January 5) drives the rate-doubling stretch: homestays from ₹1,300 to ₹2,800-3,800, mid-bracket resorts (Vythiri Resort, Banasura Hill, Wayanad Wild) from ₹5,000 to ₹10,000-14,000, luxury bracket (Wayanad Silver Woods, Stone Castle) at ₹18-25k. Wayanad Wildlife Sanctuary (Tholpetty + Muthanga ranges) Forest Department jeep safari at full schedule (₹400/person, 7-9am and 3-4pm batches) — online booking lead at muthanga.kerala.gov.in extends from 1-2 days off-peak to 3-5 days through Christmas-NY. Chembra Peak trek (2050m, heart-shaped lake midway, 7km moderate, online booking ₹750 group at Meppadi Forest Department) — slots tighten to 5-7 day lead through holiday week. Edakkal Caves (8000-year-old petroglyphs, 700-step climb, ₹100, 9am-5pm closed Mon) at year-busiest. Banasura Sagar Dam (685m length, India''s largest earth dam) at peak visitor load. Tamarassery Ghat (9-hairpin Kozhikode-Wayanad approach, 100km) at year-busiest — depart Kozhikode by 7am or arrive after 6pm. Wildlife concentration at year-best as waterholes shrink visibly.'
)
